import {quantumCurveSVG} from './quantum-plots.js?v=20261110-en1';
import {crystalSpan} from './crystal-notation.js?v=20261110-en1';
import {mathHTML} from './math-display.js?v=20261113-prose2';
import {captureCalculation,RELEASE} from './material-notebook.js?v=20261113-route1';

const KEY='symmetry-lab.shg-flagship.progress.v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>Number.isFinite(x)?Number(x.toPrecision(5)):'—';
const inlineMath=(tex,source=tex)=>`<span class="sl-math" data-math-source="${esc(source)}">${mathHTML(tex)}</span>`;
const formula=tex=>`<div class="shg-equation sl-math" data-math-source="${esc(tex)}">${mathHTML(tex,true)}</div>`;
export const SHG_MATERIALS=[
 {id:'si',title:"Si · diamond structure",model:'centrosymmetric',group:'O_h',hm:'m-3m',phase:"Ideal, unstrained bulk diamond structure",coefficients:{},cOverA:1},
 {id:'gaas',title:"GaAs · zinc blende",model:'gaas',group:'T_d',hm:'-43m',phase:"Bulk zinc-blende structure",coefficients:{xyz:1},cOverA:1},
 {id:'bto',title:"BaTiO₃ · tetragonal ferroelectric phase",model:'batio3',group:'C_{4v}',hm:'4mm',phase:"Single domain, with the polar axis along crystal z; this is not the cubic paraelectric phase",coefficients:{xxz:1,zxx:.7,zzz:1.5},cOverA:1.01}
];
export const shgInput=(material,geometry)=>({model:material.model,coefficients:{...material.coefficients},cOverA:material.cOverA,cut:geometry.cut,incidence:geometry.incidence,azimuth:geometry.azimuth,channel:geometry.channel,samples:73});
let latest=null;
export const getSHGFlagshipResult=()=>latest;
const curve=(records,channel)=>quantumCurveSVG(records.map(r=>({label:r.label,points:r.result.scan.angles.map((a,i)=>[a,r.result.scan.channels[channel].intensities[i]])})),{xLabel:"Azimuth φ (°)",yLabel:"SHG intensity (common arbitrary units)"});
const table=(heads,rows)=>`<div class="shg-table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const choice=(id,value,options)=>`<select id="${id}"><option value="">Make a prediction</option>${options.map(([v,label])=>`<option value="${v}" ${value===v?'selected':''}>${label}</option>`).join('')}</select>`;

export function renderSHGFlagship({container,run,cancelRun,download,toast=()=>{}}){
 latest=null;
 let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch{}
 const predictions=Object.fromEntries(SHG_MATERIALS.map(m=>[m.id,['allowed','forbidden'].includes(saved.predictions?.[m.id])?saved.predictions[m.id]:'']));
 let predicted=Boolean(saved.predicted)&&Object.values(predictions).every(Boolean),explanation=String(saved.explanation||'').slice(0,4000),conclusion=String(saved.conclusion||'').slice(0,4000),counterPrediction=['yes','no'].includes(saved.counterPrediction)?saved.counterPrediction:'';
 let geometry={cut:'001',incidence:45,azimuth:30,channel:'PP'},records=[],counter=[],conceptPassed=false,completed=false,busy=false,ticket=0,status='',q1='',q2='',inference='';
 container.innerHTML='<article class="shg-story"></article>';const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>container.isConnected!==false&&root.parentNode===container;
 const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify({predictions,predicted,explanation,conclusion,counterPrediction}));}catch{status="The browser could not save your draft. You can export the report when the experiment is complete.";}};
 const clearCompletion=()=>{completed=false;latest=null;if($('#shg-completion'))$('#shg-completion').innerHTML='';};
 const report=()=>({format:'symmetry-lab-shg-flagship',version:1,release:RELEASE,created:new Date().toISOString(),scope:"Ideal bulk electric-dipole SHG with degenerate input frequencies and only j↔k permutation symmetry imposed; illustrative coefficients and common arbitrary intensity units.",geometry:{...geometry},predictions:{...predictions},calculations:records,counterPrediction,counterexamples:counter,explanation,conclusion,assessment:{conceptPassed,completed,freeText:"Your written explanation has been recorded; its physical correctness has not been graded automatically."}});
 const remember=()=>{const last=counter.at(-1);if(!last)return;const result={...last.result,learningEvidence:{flagship:report()}};latest={tool:'shg_lab',input:last.input,result};captureCalculation('shg_lab',last.input,result,{route:'compute/shg-flagship',title:"Si / GaAs / BaTiO₃ · SHG flagship experiment report",material:'Si; GaAs; tetragonal BaTiO3'});};
 function invalidate(){records=[];counter=[];conceptPassed=false;completed=false;latest=null;status="The geometry has changed. Recalculate and check your explanation against the new results.";}
 async function calculate(kind){
  if(busy||!predicted||kind==='counter'&&(!conceptPassed||!counterPrediction))return;
  const request=++ticket;busy=true;completed=false;latest=null;status="Starting Python in your browser. The first load may take a little time…";draw();
  const active=()=>current()&&ticket===request;
  try{
   const inputs=kind==='main'?SHG_MATERIALS.map(m=>({id:m.id,label:m.title,input:shgInput(m,geometry)})):[0,45].map(theta=>({id:String(theta),label:"GaAs (001) · incidence  "+theta+'°',input:shgInput(SHG_MATERIALS[1],{cut:'001',incidence:theta,azimuth:30,channel:'PP'})}));
   const results=[];
   for(const item of inputs){if(!active())return;status="Calculating  "+item.label+'…';$('#shg-status').textContent=status;const result=await run('shg_lab',item.input);if(!active())return;results.push({...item,result});}
   if(kind==='main'){records=results;counter=[];conceptPassed=false;}else counter=results;
   status=kind==='main'?"All three materials have been calculated. Compare your predictions with the results, then complete your explanation.":"The counterexample is ready. Check whether inversion symmetry and a detected signal carry equivalent information.";
  }catch(error){if(active())status="Calculation not completed: "+error.message+". You can try again; your predictions and notes remain on this page.";}
  finally{if(active()){busy=false;draw();}}
 }
 function draw(){
  if(!current())return;
  root.innerHTML=`<header class="shg-intro"><span class="obs-eyebrow">Flagship experiment · allow 25–35 minutes</span><h2>Does the absence of an SHG signal prove inversion symmetry?</h2><p>Use Si, GaAs, and tetragonal BaTiO₃ to work through a complete experiment: make a prediction, calculate the evidence, explain the mechanism, and test a counterexample.</p><p>Prerequisites: point groups, inversion, vectors, and matrices. By the end, you should distinguish a forbidden tensor, an allowed tensor, and a nonzero signal in a particular measurement channel.</p><div class="shg-stages" aria-label="Experiment progress">${[["Predict",predicted],["Calculate",records.length===3],["Explain",conceptPassed],["Counterexample",completed]].map(([name,done],i)=>`<span class="${done?'done':''}">${i+1} · ${name}${done?' ✓':''}</span>`).join('')}</div></header>
  <aside class="shg-scope"><strong>What does this experiment calculate?</strong><p>The model calculates ideal bulk electric-dipole second-harmonic generation. Surface, interface, electric-quadrupole, and other contributions in Si are excluded. BaTiO₃ is fixed to a tetragonal, single-domain ferroelectric phase. All three materials use illustrative coefficients, so the results do not compare their actual absolute SHG efficiencies.</p><p>Drafts are saved in this browser. Results must be recalculated after you refresh or leave the page. Once complete, you can export all numerical results and explanations.</p></aside>
  <section class="shg-step"><h3>1 · Predict: which bulk phases allow electric-dipole SHG?</h3><p>Allowed means only that symmetry does not force every second-order tensor component to vanish. Make your own prediction first; your original choices will be retained.</p><div class="shg-materials">${SHG_MATERIALS.map(m=>`<article><h4>${m.title}</h4><p>${inlineMath(m.group)}（${crystalSpan(m.hm)}） · ${m.phase}</p><label><span>My prediction</span>${choice('shg-p-'+m.id,predictions[m.id],[['forbidden',"Forbidden by symmetry"],['allowed',"Allowed by symmetry"]])}</label></article>`).join('')}</div><button id="shg-predict" class="primary" ${predicted?'disabled':''}>${predicted?"Prediction recorded":"Record predictions and start"}</button><p>A prediction that disagrees with the result is useful evidence too. You can continue without first choosing the correct answer.</p></section>
  <section class="shg-step"><h3>2 · Calculate: from tensor constraints to polarization signals</h3><div class="shg-controls"><label><span>Surface plane</span><select id="shg-cut">${['001','111'].map(v=>`<option value="${v}" ${geometry.cut===v?'selected':''}>(${v})</option>`).join('')}</select></label><label><span>Incidence angle θ (°, from the surface normal)</span><input id="shg-incidence" type="number" min="0" max="85" step="1" value="${geometry.incidence}"></label><label><span>Azimuth φ (°)</span><input id="shg-azimuth" type="number" min="0" max="360" step="1" value="${geometry.azimuth}"></label><label><span>Polarization channel (incident → detected)</span><select id="shg-channel">${['PP','PS','SP','SS'].map(v=>`<option value="${v}" ${geometry.channel===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p>P lies in the plane of incidence and S is perpendicular to it. The incidence plane is the laboratory xz plane. Curves scan the azimuth; the table reports the selected angle. All curves use common arbitrary units and are not normalized individually.</p><details><summary>Illustrative coefficients and crystal-axis conventions</summary><p>GaAs: χ_{xyz} = 1, with equal values for all permutations of three distinct indices. BaTiO₃: χ_{xxz} = χ_{xzx} = χ_{yyz} = χ_{yzy} = 1, χ_{zxx} = χ_{zyy} = 0.7, χ_{zzz} = 1.5, and c/a = 1.01. Si: all components are zero. Full Kleinman permutation symmetry is not imposed on BaTiO₃.</p><p>For (001), the initial crystal axes align with the laboratory axes. For (111), the existing SHG core constructs the initial orientation from the surface normal. The actual orientation matrix is included in the report. Fresnel factors, absorption, phase matching, and surface contributions are neglected.</p></details><button id="shg-calculate" class="primary" ${!predicted||busy?'disabled':''}>Calculate all three materials</button><button id="shg-cancel" class="secondary" ${busy?'':'hidden'}>Cancel this calculation</button><p id="shg-status" role="status" aria-live="polite">${esc(status||"First record a prediction for each of the three materials.")}</p><div id="shg-results">${records.length===3?table(["Material","Original prediction","Inversion present","Independent components","Intensity at selected angle","Prediction check"],records.map(r=>[esc(r.label),predictions[r.id]==='allowed'?"Allowed":"Forbidden",r.result.symmetry.inversionPresent?"Yes":"No",r.result.tensor.dimension,num(r.result.selection.intensity),(r.result.tensor.dimension>0)===(predictions[r.id]==='allowed')?"Agrees":"Revise your explanation"]))+curve(records,geometry.channel)+`<details><summary>Inspect the group projector and tensor basis</summary>${records.map(r=>`<h4>${esc(r.label)}</h4><p>Dimension from the group projector: ${r.result.symmetry.dimensionFromGroupProjector}; covariance residual: ${num(r.result.symmetry.covarianceResidual)}。</p><pre>${esc(JSON.stringify(r.result.tensor.basis,null,2))}</pre>`).join('')}</details>`:''}</div></section>
  <section class="shg-step"><h3>3 · Explain: why are there 0, 1, and 3 independent components?</h3><p>Complete the calculation, expand the derivation one step at a time, and write your own explanation.</p><details><summary>Derivation ① · How inversion constrains an odd-rank polar tensor</summary>${formula(String.raw`P_i(2\omega)=\varepsilon_0\sum_{jk}\chi^{(2)}_{ijk}E_j(\omega)E_k(\omega)`)}<p>Under inversion, both polarization and electric field change sign, whereas the product of two electric fields does not. If the material is invariant under inversion, its response coefficient must satisfy:</p>${formula(String.raw`\chi^{(2)}=-\chi^{(2)}\quad\Longrightarrow\quad\chi^{(2)}=0`)}<p>Electric-dipole SHG is therefore forbidden in ideal bulk Si. This does not rule out surface SHG.</p></details><details><summary>Derivation ② · Which tensor components survive the group projector?</summary>${formula(String.raw`\Pi=\frac{1}{|G|}\sum_{R\in G}R\otimes R\otimes R`)}<p>Find the invariant subspace within the tensor space symmetric under exchange of its last two indices. Oh, Td, and C4v give dimensions 0, 1, and 3, respectively. The absence of inversion removes only the inversion constraint; the full point group must still be checked.</p></details><details><summary>Derivation ③ · Why does allowed not guarantee a nonzero channel?</summary>${formula(String.raw`A=\mathbf e_{\mathrm{out}}\cdot\mathbf P(2\omega),\qquad I\propto |A|^2`)}<p>The nonlinear polarization must also be projected onto the detected polarization. Geometry, polarization, or cancellation between components can make the amplitude vanish. Here the incident field has unit amplitude, and common constants are absorbed into the arbitrary intensity unit.</p></details><div class="shg-controls"><label><span>What does the inversion constraint act on?</span>${choice('shg-q1',q1,[['tensor',"All bulk electric-dipole second-order tensor components"],['channel',"Only the PP channel"]])}</label><label><span>What does an allowed tensor imply?</span>${choice('shg-q2',q2,[['possible',"A nonzero response component is permitted by symmetry"],['always',"Every geometry and every channel must produce a signal"]])}</label></div><label><span>My explanation: connect inversion, the tensor, and the measurement projection to explain the three materials</span><textarea id="shg-explanation" rows="4" maxlength="4000">${esc(explanation)}</textarea></label><button id="shg-explain" class="primary" ${records.length!==3||busy?'disabled':''}>Check concepts and save explanation</button><p id="shg-explanation-status">${conceptPassed?"The concept check is complete. Your explanation has been recorded; review it against the derivation or ask an instructor to assess it.":''}</p></section>
  <section class="shg-step"><h3>4 · Test a counterexample: keep the GaAs point group and change the geometry</h3><p>Keep GaAs (001), the same nonzero tensor, and φ = 30° fixed. Compare normal incidence at θ = 0° with oblique incidence at θ = 45°. Predict first, then calculate.</p><label><span>If all polarization channels vanish at normal incidence, can you conclude that the material has inversion symmetry?</span>${choice('shg-counter-prediction',counterPrediction,[['yes',"Yes: a zero signal establishes inversion symmetry"],['no',"No: geometric and polarization-projection effects must also be checked"]])}</label><button id="shg-counter" class="primary" ${!conceptPassed||!counterPrediction||busy?'disabled':''}>Calculate and compare both geometries</button><div id="shg-counter-results">${counter.length===2?table(["Geometry","Inversion present","Independent components","PP intensity at selected angle","Maximum across all four channel scans"],counter.map(r=>[esc(r.label),r.result.symmetry.inversionPresent?"Yes":"No",r.result.tensor.dimension,num(r.result.selection.intensity),num(Math.max(...Object.values(r.result.scan.channels).flatMap(c=>c.intensities)))]))+curve(counter,'PP')+`<details><summary>Explain this counterexample step by step</summary><p>① Both calculations use exactly the same crystal, group operations, and tensor. Neither has inversion symmetry, and both retain one independent component.</p><p>② At normal incidence, the incident electric field lies in the xy plane. The nonzero GaAs components require three distinct indices, so the induced polarization points along z and has no projection onto the transverse detection polarizations. All four channels therefore vanish.</p><p>③ Oblique incidence introduces a z component of the polarization and changes the outgoing projection, giving a signal in at least one channel. The measurement geometry changes; the material's point group does not.</p><p>④ A single zero signal therefore cannot establish inversion symmetry. Real experiments must also consider detection sensitivity, surface contributions, and higher multipoles.</p></details>`:''}</div><label><span>Conclusion after checking the evidence</span>${choice('shg-inference',inference,[['geometry',"A zero signal does not establish inversion; check the geometry, channel, and model assumptions"],['inversion',"GaAs acquires inversion symmetry at normal incidence"]])}</label><label><span>Report conclusion: cite a numerical result and state what evidence would change your judgment</span><textarea id="shg-conclusion" rows="4" maxlength="4000">${esc(conclusion)}</textarea></label><button id="shg-complete" class="primary" ${counter.length!==2||busy?'disabled':''}>Complete experiment and create report</button><div id="shg-completion">${completed?"<p class=\"shg-success\">All four stages are documented. The concept answers have been checked; review the written explanations yourself or with an instructor.</p><button id=\"shg-export\" class=\"secondary\">Export complete experiment JSON</button><a href=\"#atlas/notebook\">Open the material notebook and add this report →</a>":''}</div></section>
  <footer class="shg-step"><h3>Explore further</h3><button id="shg-restart" class="secondary" ${busy?'disabled':''}>Restart this experiment (clear draft)</button><p>Export any report you want to keep before starting again. This clears only this experiment's draft, not your material notebook.</p><p>Project assignment: change χ_{zzz} for BaTiO₃ in the full SHG calculator while keeping the point group fixed. Compare PP with SS, explain the difference between changing a coefficient and changing a symmetry, and add the results to the same material project.</p><div class="shg-links"><a href="#compute/shg-lab">Full SHG calculator</a><a href="#compute/tensors">Property-tensor constraints</a><a href="#atlas">Materials atlas</a><a href="#classroom/crystal?tab=materials&material=silicon">Si crystal-structure lesson</a><a href="#classroom/crystal?tab=materials&material=gaas">GaAs crystal-structure lesson</a></div><p>Further reading: <a href="https://bfichera.github.io/shgpy/" target="_blank" rel="noopener">ShgPy rotational-anisotropy SHG tutorials</a>；<a href="https://wiki.yambo-code.eu/wiki/index.php?title=Angular_dependence_of_non-linear_response" target="_blank" rel="noopener">Yambo tutorial on the angular dependence of nonlinear response</a>. This site runs its existing Python teaching core; it does not call either external program.</p></footer>`;
  for(const m of SHG_MATERIALS){const input=$('#shg-p-'+m.id);input.disabled=predicted||busy;input.onchange=()=>{predictions[m.id]=input.value;persist();};}
  $('#shg-predict').onclick=()=>{if(Object.values(predictions).some(x=>!x)){status="Choose a prediction for each of the three materials first.";draw();return;}predicted=true;persist();status="Your predictions have been recorded. You can now calculate.";draw();};
  for(const key of ['cut','incidence','azimuth','channel']){const input=$('#shg-'+key);input.disabled=busy;input.onchange=()=>{const value=['incidence','azimuth'].includes(key)?Number(input.value):input.value;if(['incidence','azimuth'].includes(key)&&(!Number.isFinite(value)||input.value.trim()===''||value<0||value>(key==='incidence'?85:360))){status="Enter an angle within the stated range.";draw();return;}geometry[key]=value;invalidate();draw();};}
  $('#shg-calculate').onclick=()=>calculate('main');$('#shg-counter').onclick=()=>calculate('counter');
  $('#shg-cancel').onclick=()=>{++ticket;busy=false;cancelRun?.();status="This calculation has been cancelled. Incomplete results will not count as experimental evidence.";draw();};
  $('#shg-q1').onchange=e=>{q1=e.target.value;conceptPassed=false;clearCompletion();if($('#shg-counter'))$('#shg-counter').disabled=true;};$('#shg-q2').onchange=e=>{q2=e.target.value;conceptPassed=false;clearCompletion();if($('#shg-counter'))$('#shg-counter').disabled=true;};
  $('#shg-explanation').oninput=e=>{explanation=e.target.value.slice(0,4000);clearCompletion();persist();};
  $('#shg-explain').onclick=()=>{conceptPassed=q1==='tensor'&&q2==='possible'&&Boolean(explanation.trim());status=conceptPassed?"Concept check passed. Now test the geometric counterexample in GaAs.":"Review all three derivation steps, check the concepts again, and write your own explanation.";persist();draw();};
  $('#shg-counter-prediction').disabled=counter.length>0||busy;$('#shg-counter-prediction').onchange=e=>{counterPrediction=e.target.value;persist();draw();};
  $('#shg-inference').onchange=e=>{inference=e.target.value;clearCompletion();};$('#shg-conclusion').oninput=e=>{conclusion=e.target.value.slice(0,4000);clearCompletion();persist();};
  $('#shg-complete').onclick=()=>{completed=records.length===3&&counter.length===2&&conceptPassed&&inference==='geometry'&&Boolean(conclusion.trim())&&Boolean(explanation.trim());status=completed?"The complete experiment report is ready.":"Check your conclusion and provide an explanation supported by numerical evidence. You do not need to change your original predictions.";persist();if(completed)remember();draw();};
  if($('#shg-export'))$('#shg-export').onclick=()=>{if(!completed){toast("Your explanation has changed. Complete the experiment again to update the report.");return;}download(JSON.stringify(report(),null,2),'shg-flagship-report.json','application/json');};
  $('#shg-restart').onclick=()=>{if(busy)return;for(const m of SHG_MATERIALS)predictions[m.id]='';predicted=false;explanation=conclusion=counterPrediction=q1=q2=inference='';geometry={cut:'001',incidence:45,azimuth:30,channel:'PP'};invalidate();status="A new experiment has started. Record fresh predictions.";persist();draw();};
  if(busy)for(const tag of ['select','textarea'])root.querySelectorAll(tag).forEach(el=>el.disabled=true);
 }
 draw();
}
